"""Generate text_to_sql benchmark prompts.

Each prompt contains:
  - id: unique identifier
  - category: "text_to_sql"
  - difficulty: "simple" | "medium" | "complex"
  - system_prompt: instructions for the AI
  - user_prompt: the user's question
  - context: injected context (schemas, documents, logs, etc.)
  - expected_answer: reference answer for judge evaluation
"""
import json
import os

# Write generated JSON into the parent generated/ dir (alongside the committed datasets)
PROMPTS_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.makedirs(PROMPTS_DIR, exist_ok=True)


def save(filename, data):
    path = os.path.join(PROMPTS_DIR, filename)
    with open(path, "w") as f:
        json.dump(data, f, indent=2)
    print(f"  {filename}: {len(data)} prompts")


